Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Notation SEGS := asegs (only parsing).
Local Ltac xms H := first [exact H | apply msteps_bridge; exact H].

Definition OP_ENTRY : Z := 0x123898.
Definition OP_RET : Z := 0x1239b8.
Definition OP_RETPC : Z := 0x123a00.
Definition OP_FR : Z := 80.

Definition op_xok (xenc : Z) : Prop := exists x, 0 <= x < 2 ^ 32 /\ xenc = LbA_DiagStmt.sx32 x.

Lemma zext32_sx32 : forall x, 0 <= x < 2 ^ 32 ->
