    ad_cs : forall r, In r [22; 23; 24; 25; 26; 27]%bv -> getr R1 r = getr R r;
    ad_rf : rfull R1 }.

  Lemma op_pre : exists R1 M1 sv21 v,
    HExec.msteps SEGS (@mkst (PropExec.mkFP F fc) R (Z_to_bv 64 OP_ENTRY) M (seg_rom SEGS)) (@mkst (PropExec.mkFP F fc) R1 (Z_to_bv 64 A_NUMPUT_UL) M1 (seg_rom SEGS))
