      /\ stores_in (zwin (sp - 96) (sp - 80)) M3 M4
      /\ getr R4 1%bv = Z_to_bv 64 ret /\ getr R4 2%bv = Z_to_bv 64 sp /\ getr R4 10%bv = Z_to_bv 64 ds
      /\ (forall r, In r NCS -> getr R4 r = getr R r) /\ rfull R4.
Proof.
